import{_ as o,o as e,c as s,ag as i}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"科学日报 · 2026-11-02（量子物理 / 强关联 · UTe₂ 的四临界点）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/quantum-physics/science-daily-2026-11-02-quantum.md","filePath":"topics/quantum-physics/science-daily-2026-11-02-quantum.md"}'),c={name:"topics/quantum-physics/science-daily-2026-11-02-quantum.md"};function n(r,t,a,d,l,u){return e(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="科学日报-·-2026-11-02-量子物理-强关联-·-ute2-的四临界点" tabindex="-1">科学日报 · 2026-11-02（量子物理 / 强关联 · UTe₂ 的四临界点） <a class="header-anchor" href="#科学日报-·-2026-11-02-量子物理-强关联-·-ute2-的四临界点" aria-label="Permalink to &quot;科学日报 · 2026-11-02（量子物理 / 强关联 · UTe₂ 的四临界点）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-02.md</code> — 第52期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-quantum</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-11-02-量子物理-·-1-1-ute2-的四临界点——声速跳变给出「多分量超导」的直接热力学证据" tabindex="-1">科学日报 2026-11-02（量子物理 · 1/1）：UTe₂ 的四临界点——声速跳变给出「多分量超导」的直接热力学证据 <a class="header-anchor" href="#科学日报-2026-11-02-量子物理-·-1-1-ute2-的四临界点——声速跳变给出「多分量超导」的直接热力学证据" aria-label="Permalink to &quot;科学日报 2026-11-02（量子物理 · 1/1）：UTe₂ 的四临界点——声速跳变给出「多分量超导」的直接热力学证据&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-02.md</code> ｜ DOI: 10.1038/s41567-026-03504-z ｜ Nature Physics (2026)</p></blockquote><ul><li>问题：候选<strong>拓扑超导体 UTe₂</strong> 具有复杂相图与<strong>多个超导态</strong>，其共存本质尚未澄清；更棘手的是，压力—温度相图中<strong>两条二阶相界看似在三相点相交</strong>，这在<strong>热力学上是被禁止的</strong>——暗示要么存在<strong>隐藏相变</strong>，要么对该材料超导的理解有误。</li><li>方法：用<strong>声速测量</strong>寻找被忽略的相界，聚焦<strong>冷却过程中超导序消失</strong>所对应的热力学特征。</li><li>结果（实测）： <ul><li>观测到<strong>一条额外的相界，其特征是声速向上跳变</strong>——这是<strong>冷却时超导序消失</strong>的<strong>直接热力学证据</strong>；</li><li>结果确立了一个<strong>四临界点（tetracritical point）</strong>，越过该点后<strong>环境压力与压力诱导的超导序参量形成多分量态</strong>；</li><li>测得的相图表明两个超导序参量之间存在<strong>强竞争</strong>，正是它驱动<strong>冷却时的序丢失</strong>，并导致<strong>相位锁定</strong>，从而<strong>抑制超导涨落</strong>。</li></ul></li><li>洞察（对本库 <code>quantum-physics</code> × <code>physics</code>）： <ol><li><strong>「热力学禁不起的相图 = 藏着未观测到的相变」</strong> —— 判据：<strong>当相图出现热力学禁止的相交时，先假设存在未观测到的相界，而不是先怀疑实验本身。</strong></li><li><strong>「声速跳变是一阶相变的指纹」</strong> —— 判据：<strong>要在强关联材料里找一个难见的相变，先测声速这类热力学量找它的跳变</strong>，而不是只做输运或磁化。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/quantum-physics/index.md</code> ｜ <code>topics/physics/index.md</code> ｜ 第52期 科学板块</p></blockquote><p>关键词：科学日报第52期、UTe2、拓扑超导体、多分量超导、四临界点 tetracritical point、声速跳变、磁场压力温度相图、隐藏相变、热力学禁止的相交、序参量强竞争、相位锁定、超导涨落抑制、强关联电子</p><p>关联：<code>topics/quantum-physics/index.md</code>、<code>topics/quantum-physics/science-daily-2026-10-30-quantum.md</code>、<code>topics/physics/index.md</code>、<code>topics/physics/science-daily-2026-11-02-physics.md</code>、<code>topics/materials/index.md</code></p>',10)])])}const m=o(c,[["render",n]]);export{g as __pageData,m as default};
